using System;using System.Globalization;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Shapes;
namespace Lumina {
    public sealed partial class WidgetWindow {
        TextBlock posterDay,posterMonth,orbitLabel,clockPeriod;RotateTransform hourRotation,minuteRotation;Path orbitArc;string clockStamp="";
        void ResetAdvancedClock(){posterDay=posterMonth=orbitLabel=clockPeriod=null;hourRotation=minuteRotation=null;orbitArc=null;clockStamp="";}
        TextBlock ClockText(double size,string font=null){var text=new TextBlock{FontSize=size,Foreground=StyleInk("clock"),FontWeight=FontWeights.Light};if(!string.IsNullOrEmpty(font))text.FontFamily=new FontFamily(font);return text;}
        Border ClockRule(double width=40){return new Border{Width=width,Height=1,Background=StyleInk("clock"),Opacity=.45,Margin=new Thickness(0,10,0,10),HorizontalAlignment=HorizontalAlignment.Center};}
        void AdvancedClock(StackPanel body,WidgetStyle s){
            string family=string.IsNullOrEmpty(s.Font)?null:s.Font;
            if(s.ClockStyle==13){
                var digits=new StackPanel{HorizontalAlignment=HorizontalAlignment.Center};clockHours=ClockText(s.ClockSize*1.55,family??"Segoe UI Semibold");clockMinutes=ClockText(s.ClockSize*1.55,family??"Segoe UI Semibold");clockHours.FontWeight=clockMinutes.FontWeight=FontWeights.Bold;clockHours.LineHeight=clockMinutes.LineHeight=s.ClockSize*1.5;digits.Children.Add(clockHours);var line=new StackPanel{Orientation=Orientation.Horizontal};line.Children.Add(clockMinutes);clockPeriod=ClockText(Math.Max(12,s.ClockSize*.28));clockPeriod.VerticalAlignment=VerticalAlignment.Bottom;clockPeriod.Margin=new Thickness(5,0,0,8);clockPeriod.Visibility=!s.Hour24&&s.ShowAmPm?Visibility.Visible:Visibility.Collapsed;line.Children.Add(clockPeriod);digits.Children.Add(line);body.Children.Add(digits);date.HorizontalAlignment=HorizontalAlignment.Center;date.FontSize=15;body.Children.Add(date);
            }else if(s.ClockStyle==5){
                weekday=ClockText(34);weekday.FontWeight=FontWeights.SemiBold;body.Children.Add(new Viewbox{Child=weekday,Stretch=Stretch.Uniform,MaxHeight=45,Margin=new Thickness(0,4,0,4)});body.Children.Add(ClockRule(34));date.HorizontalAlignment=clock.HorizontalAlignment=HorizontalAlignment.Center;date.FontSize=12;clock.FontSize=s.ClockSize*.68;body.Children.Add(date);body.Children.Add(clock);
            }else if(s.ClockStyle==6||s.ClockStyle==12){
                var row=new Grid();row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(s.ClockStyle==6?125:90)});row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(18)});row.ColumnDefinitions.Add(new ColumnDefinition());
                var badge=new StackPanel{VerticalAlignment=VerticalAlignment.Center};posterMonth=ClockText(12);posterMonth.HorizontalAlignment=HorizontalAlignment.Center;posterDay=ClockText(s.ClockStyle==6?84:56,s.ClockStyle==6?"Georgia":null);posterDay.HorizontalAlignment=HorizontalAlignment.Center;
                badge.Children.Add(posterMonth);badge.Children.Add(posterDay);row.Children.Add(badge);var line=new Border{Width=1,Background=StyleInk("clock"),Opacity=.3,Margin=new Thickness(0,12,0,12)};Grid.SetColumn(line,1);row.Children.Add(line);badge.Visibility=line.Visibility=s.ShowDate?Visibility.Visible:Visibility.Collapsed;if(!s.ShowDate){row.ColumnDefinitions[0].Width=new GridLength(0);row.ColumnDefinitions[1].Width=new GridLength(0);}
                var right=new StackPanel{VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(8,0,0,0)};Grid.SetColumn(right,2);weekday=ClockText(s.ClockStyle==6?17:13);weekday.FontWeight=FontWeights.Medium;right.Children.Add(weekday);clock.FontSize=s.ClockStyle==6?s.ClockSize*.83:s.ClockSize*.7;right.Children.Add(clock);right.Children.Add(date);row.Children.Add(right);body.Children.Add(row);
            }else if(s.ClockStyle==7){
                var row=new Grid();row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(135)});row.ColumnDefinitions.Add(new ColumnDefinition());var digits=new StackPanel();clockHours=ClockText(s.ClockSize*1.55,family??"Segoe UI Light");clockMinutes=ClockText(s.ClockSize*1.55,family??"Segoe UI Light");clockHours.LineHeight=clockMinutes.LineHeight=s.ClockSize*1.5;digits.Children.Add(clockHours);digits.Children.Add(clockMinutes);row.Children.Add(digits);var info=new StackPanel{VerticalAlignment=VerticalAlignment.Bottom,Margin=new Thickness(16,0,0,12)};Grid.SetColumn(info,1);weekday=ClockText(19);weekday.FontWeight=FontWeights.SemiBold;info.Children.Add(weekday);info.Children.Add(ClockRule(30));date.TextWrapping=TextWrapping.Wrap;info.Children.Add(date);row.Children.Add(info);body.Children.Add(row);
            }else if(s.ClockStyle==8||s.ClockStyle==9){
                var circle=new Grid{Width=184,Height=184,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,4,0,8)};
                circle.Children.Add(new Ellipse{Stroke=StyleInk("clock"),StrokeThickness=1,Opacity=.25,Margin=new Thickness(5)});
                if(s.ClockStyle==8){
                    var ticks=new Canvas{Width=184,Height=184};for(int i=0;i<12;i++){double a=i*Math.PI/6;double r=i%3==0?74:79;ticks.Children.Add(new Line{X1=92+Math.Sin(a)*r,Y1=92-Math.Cos(a)*r,X2=92+Math.Sin(a)*84,Y2=92-Math.Cos(a)*84,Stroke=StyleInk("clock"),StrokeThickness=i%3==0?2:1,Opacity=.65});}circle.Children.Add(ticks);
                    hourRotation=new RotateTransform(0,92,92);minuteRotation=new RotateTransform(0,92,92);var hour=new Line{X1=92,Y1=100,X2=92,Y2=45,Stroke=StyleInk("clock"),StrokeThickness=3,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round,RenderTransform=hourRotation};var minute=new Line{X1=92,Y1=103,X2=92,Y2=22,Stroke=StyleInk("clock"),StrokeThickness=1.5,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round,RenderTransform=minuteRotation};ticks.Children.Add(hour);ticks.Children.Add(minute);circle.Children.Add(new Ellipse{Width=6,Height=6,Fill=StyleInk("clock"),HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center});body.Children.Add(circle);clock.FontSize=s.ClockSize*.62;clock.HorizontalAlignment=HorizontalAlignment.Center;body.Children.Add(clock);
                }else{orbitArc=new Path{Stroke=StyleInk("clock"),StrokeThickness=3,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round};circle.Children.Add(orbitArc);var info=new StackPanel{VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center};clock.FontSize=s.ClockSize*.65;clock.HorizontalAlignment=HorizontalAlignment.Center;orbitLabel=ClockText(10);orbitLabel.HorizontalAlignment=HorizontalAlignment.Center;info.Children.Add(clock);info.Children.Add(orbitLabel);circle.Children.Add(new Viewbox{Child=info,Width=150,Height=95,Stretch=Stretch.Uniform,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center});body.Children.Add(circle);}
                date.HorizontalAlignment=HorizontalAlignment.Center;body.Children.Add(date);
            }else if(s.ClockStyle==10){clock.FontFamily=new FontFamily(family??"Georgia");clock.FontStyle=FontStyles.Italic;clock.FontSize=s.ClockSize*1.15;clock.HorizontalAlignment=HorizontalAlignment.Center;body.Children.Add(ClockRule(80));body.Children.Add(clock);body.Children.Add(ClockRule(80));date.FontSize=12;date.HorizontalAlignment=HorizontalAlignment.Center;body.Children.Add(date);
            }else{
                var row=new Grid();row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});weekday=ClockText(12,"Consolas");weekday.FontWeight=FontWeights.Bold;row.Children.Add(weekday);var tag=ClockText(10,"Consolas");tag.Text=s.Hour24?"24 小时":"12 小时";Grid.SetColumn(tag,1);row.Children.Add(tag);body.Children.Add(row);clock.FontFamily=new FontFamily(family??"Consolas");clock.FontSize=s.ClockSize*1.08;body.Children.Add(clock);date.FontFamily=new FontFamily("Consolas");date.FontSize=12;body.Children.Add(date);
            }
        }
        void AdvancedClockTick(DateTime now,WidgetStyle style){
            if(style.ClockStyle<5)return;SetText(clockPeriod,ClockCatalog.PeriodLabel(now));SetText(weekday,ClockCatalog.Weekday(now,style.ClockStyle));SetText(date,ClockCatalog.DateLabel(now,style.ClockStyle));SetText(posterDay,now.ToString("dd"));SetText(posterMonth,ClockCatalog.MonthLabel(now));
            string minute=now.ToString("yyyyMMddHHmm");if(clockStamp==minute)return;clockStamp=minute;
            if(hourRotation!=null)hourRotation.Angle=ClockCatalog.HourAngle(now);if(minuteRotation!=null)minuteRotation.Angle=ClockCatalog.MinuteAngle(now);
            if(orbitArc!=null){double fraction=ClockCatalog.DayFraction(now),angle=fraction*Math.PI*2;var geometry=new PathGeometry();if(fraction>0){var figure=new PathFigure{StartPoint=new Point(92,5),IsClosed=false};figure.Segments.Add(new ArcSegment(new Point(92+87*Math.Sin(angle),92-87*Math.Cos(angle)),new Size(87,87),0,fraction>.5,SweepDirection.Clockwise,true));geometry.Figures.Add(figure);}orbitArc.Data=geometry;SetText(orbitLabel,"今日  "+Math.Floor(fraction*100)+"%");}
        }
    }
}
